import java.util.Scanner;
class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int arr[] = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        for (int k = 1; k <= n - 1; k++) {
            int ptr = 0;
            while (ptr <= n - k - 1) {
                if (arr[ptr] < arr[ptr + 1]) {
                    int temp = arr[ptr];
                    arr[ptr] = arr[ptr + 1];
                    arr[ptr + 1] = temp;
                }
                ptr++;
            }
        }
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

