import java.util.Scanner;
class Main {
    static void bubble(int arr[], int n) {
        if (n == 1) {
            return;
        }
        int ptr = 0;
        while (ptr <= n - 2) {
            if (arr[ptr] < arr[ptr + 1]) {
                int temp = arr[ptr];
                arr[ptr] = arr[ptr + 1];
                arr[ptr + 1] = temp;
            }
            ptr++;
        }
        bubble(arr, n - 1);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int arr[] = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        bubble(arr, n);
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

