#include <stdio.h>

int main() {
    int n, i, k, temp;

    // Step 1: Ask user for number of elements.
    // This value tells us how many numbers we need to sort.
    printf("Enter number of elements: ");
    scanf("%d", &n);

    // Step 2: Create an array of size n.
    // The array will store all input values.
    int arr[n];

    // Step 3: Read each element one by one.
    printf("Enter elements:\n");
    for (i = 0; i < n; i++) {
        // Ask for the next number.
        printf("Enter value: ");

        // Store the current input at index i.
        scanf("%d", &arr[i]);
    }

    // Step 4: Perform Bubble Sort in descending order.
    // The outer loop controls how many passes we make.
    for (k = 1; k <= n - 1; k++) {
        int ptr = 0;

        // The inner loop compares adjacent elements.
        // After each pass, one more element reaches its correct place.
        while (ptr <= n - k - 1) {
            // If the left value is smaller, swap them.
            if (arr[ptr] < arr[ptr + 1]) {
                // Use a temporary variable to swap safely.
                temp = arr[ptr];
                arr[ptr] = arr[ptr + 1];
                arr[ptr + 1] = temp;
            }

            // Move to the next adjacent pair.
            ptr++;
        }
    }

    // Step 5: Print the sorted array.
    printf("Sorted array:\n");
    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    return 0;
}
